# check each option: search for a non-congruent pair of triangles satisfying the condition
import itertools, math
def area(a,b,c):
    s=(a+b+c)/2; x=s*(s-a)*(s-b)*(s-c)
    return math.sqrt(x) if x>0 else None
tri=[(a,b,c) for a in range(1,13) for b in range(a,13) for c in range(b,13) if a+b>c]
def angles(t):
    a,b,c=t
    return [round(math.degrees(math.acos((b*b+c*c-a*a)/(2*b*c))),9),round(math.degrees(math.acos((a*a+c*c-b*b)/(2*a*c))),9),round(math.degrees(math.acos((a*a+b*b-c*c)/(2*a*b))),9)]
def counter(cond):
    for t1,t2 in itertools.combinations(tri,2):
        if cond(t1,t2): return True
    return False
def A(t1,t2): return bool(set(t1)&set(t2)) and bool(set(angles(t1))&set(angles(t2)))
def B(t1,t2):
    # two sides equal (as multiset) and same perimeter
    for p in itertools.combinations(t1,2):
        l=list(t2)
        try:
            l.remove(p[0]); l.remove(p[1])
        except ValueError: continue
        if sum(t1)==sum(t2): return True
    return False
def C(t1,t2):
    for b in set(t1)&set(t2):
        if abs(area(*t1)-area(*t2))<1e-9: return True
    return False
def Dd(t1,t2):
    for b in set(t1)&set(t2):
        if abs(2*area(*t1)/b-2*area(*t2)/b)<1e-9: return True
    return False
res={'A':counter(A),'B':counter(B),'C':counter(C),'D':counter(Dd)}
suff=[k for k,v in res.items() if not v]
assert suff==['B']

